Q: How do I convert a column of text URLs into active hyperlinks in Excel? A: <h1>Simpler Excel 365 OfficeScript &amp; How To</h1>
<pre><code>//Converts selected cells to clickable hyperlinks
//To use: 
//1. Select the cells you want to update to hyperlinks.
//2. Click on the &quot;Automate&quot; menu at the top
//3. Click &quot;New Script&quot; and paste this (you can include these comments).
//4. Click &quot;Run&quot; (wait for large data sets).
//5. Close the code editor.
function main(workbook: ExcelScript.Workbook) {
    const range = workbook.getSelectedRange();
    const values = range.getValues();

    const rowCount = values.length;
    const colCount = values[0]?.length ?? 0;

    for (let r = 0; r &lt; rowCount; r++) {
        for (let c = 0; c &lt; colCount; c++) {
            const cell = range.getCell(r, c);
            const raw = values[r][c];

            if (raw === null || raw === undefined) continue;

            const address = String(raw).trim();
            if (!address) continue;

            // Create/replace hyperlink on the cell
            cell.setHyperlink({ address });
        }
    }
}
</code></pre>
